import { Injectable } from '@angular/core';
import { SemiFinished } from '../pages/semi-finished/semi-finished';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../environments/environments';
@Injectable({
  providedIn: 'root'
})
export class SemiFinishedService {
   private apiUrl = `${environment.apiUrl}/SemiFinished`; 
  constructor(private http: HttpClient) {}

  getAllProducts(): Observable<SemiFinished[]> {
    return this.http.get<SemiFinished[]>(this.apiUrl);
  }
  getProductByID(id: number): Observable<SemiFinished> {
    return this.http.get<SemiFinished>(`${this.apiUrl}/${id}`)
  }
  addProduct(product: SemiFinished): Observable<SemiFinished> {
  return this.http.post<SemiFinished>(`${this.apiUrl}/create`, product);
}

updateProduct(id: number, product: SemiFinished): Observable<SemiFinished> {
  return this.http.put<SemiFinished>(`${this.apiUrl}/update/${id}`, product);
}

deleteProduct(id: number): Observable<void> {
  
  return this.http.delete<void>(`${this.apiUrl}/${id}`);
}
}
